//! Lines a boot-path stage depends on.
//!
//! A boot-path stage is reached when its marker reaches the serial port
//! (`docs/boot-path.md`), so a line carrying a marker must not be dropped or
//! split. The output paths that can lose or split a line under pressure ask
//! here whether a line carries one: the x86 kernel log ring (`log_ring`),
//! x86's bounded COM1 writer and the aarch64 UART owner (`serial_line`).
//!
//! The markers are `crate::STAGE_MARKERS`, generated by build.rs from
//! `kernel/stage_markers.rs`, sorted by their last byte so the scanner checks
//! at each byte only the markers that can end there.
//!
//! Core only: the host test `tests/stage_line_pressure.rs` compiles this file.

use core::fmt;

/// The longest marker the scanner matches. `kernel/stage_markers.rs` refuses
/// a longer one.
pub const MAX_MARKER: usize = 128;

/// Watches a line go by, byte by byte, for a marker ending in it.
pub struct Scan<'a> {
    markers: &'a [&'a str],
    window: [u8; MAX_MARKER],
    seen: usize,
    hit: bool,
}

impl<'a> Scan<'a> {
    pub fn new(markers: &'a [&'a str]) -> Self {
        Self {
            markers,
            window: [0; MAX_MARKER],
            seen: 0,
            hit: false,
        }
    }

    /// A marker has gone by.
    pub fn hit(&self) -> bool {
        self.hit
    }

    pub fn byte(&mut self, byte: u8) {
        if self.hit {
            return;
        }
        self.window[self.seen % MAX_MARKER] = byte;
        self.seen += 1;
        let first = self
            .markers
            .partition_point(|marker| last_byte(marker) < byte);
        for marker in self.markers[first..]
            .iter()
            .take_while(|marker| last_byte(marker) == byte)
        {
            if self.ends_with(marker.as_bytes()) {
                self.hit = true;
                return;
            }
        }
    }

    fn ends_with(&self, marker: &[u8]) -> bool {
        marker.len() <= self.seen.min(MAX_MARKER)
            && marker
                .iter()
                .rev()
                .enumerate()
                .all(|(back, &byte)| self.window[(self.seen - 1 - back) % MAX_MARKER] == byte)
    }
}

impl fmt::Write for Scan<'_> {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        for byte in s.bytes() {
            self.byte(byte);
        }
        Ok(())
    }
}

fn last_byte(marker: &str) -> u8 {
    marker.as_bytes().last().copied().unwrap_or(0)
}

/// `bytes` carry one of `markers`.
pub fn contains(markers: &[&str], bytes: &[u8]) -> bool {
    let mut scan = Scan::new(markers);
    for &byte in bytes {
        scan.byte(byte);
        if scan.hit() {
            return true;
        }
    }
    false
}

/// `args`, formatted, carry one of `markers`. Formats without storing the
/// text, so a line of any length can be checked.
pub fn formats(markers: &[&str], args: fmt::Arguments) -> bool {
    let mut scan = Scan::new(markers);
    let _ = fmt::write(&mut scan, args);
    scan.hit()
}
